/bin/bash -lc "python - <<'PY'
import os,time
from pathlib import Path
from bioblend.galaxy import GalaxyInstance
key = Path(os.environ['GALAXY_API_KEY_FILE']).read_text().strip()
gi = GalaxyInstance(url='https://usegalaxy.org', key=key)
hid='bbd44e69cb8906b5df1b85b9d5ce624a'
collection_ids=['096f4ad3f78621a5','158fd780a3fd7e76']
ids=[]
for cid in collection_ids:
    c=gi.histories.show_dataset_collection(hid,cid)
    for e in c['elements']:
        if e['object'].get('extension') "'!= '"'fasta':
            ids.append(e['object']['id'])
print('remaining',len(ids),flush=True)
for i,did in enumerate(ids,1):
    for attempt in range(12):
        try:
            gi.histories.update_dataset(hid,did,datatype='fasta')
            break
        except Exception as e:
            if '429' not in str(e) or attempt==11:
                raise
            time.sleep(min(8,1+attempt))
    time.sleep(0.3)
    if i%100==0: print('updated_remaining',i,flush=True)
print('updated_remaining',len(ids),flush=True)
PY"

